// by hand; edit the generator or the single-context core instead.
//
// 2-context context-switching prototype: the state has one copy per
// context, the (large) combinational datapath is shared and time
// multiplexed by a small arbiter that advances one ready context per
// clock.  Per-context behaviour is identical to snowflake_core.
//=========================================================================
`timescale 1ns / 1ps
//======================================================================
// Snowflake decoder core (streaming / frugal) -- RTL port of the reference
// implementation "localuf" (github.com/timchan0/localuf, arXiv:2406.01701).
//
// Architecture follows the Helios approach: one element per decoding-graph
// node, one link per edge, a single global stage controller; every clock is
// one timestep of the reference model.
//
// The graph tables (nodes, edges, neighbour wiring, directions, drop
// relations, commit region, syndrome injection points) are NOT hard-coded:
// build_scripts/generate_snowflake.py exports them from localuf itself
// (repetition or surface code, any d) into design/generated/.
//
// ONE_ONE = 0 -> 2:1 growth schedule (Snowflake):
//                DROP -> GROW_WHOLE -> MERGING_WHOLE* -> GROW_HALF -> MERGING_HALF*
// ONE_ONE = 1 -> 1:1 growth schedule (baseline used for the comparison):
//                DROP -> GROW -> MERGING*
//======================================================================
`include "../generated/snowflake_graph.svh"

module snowflake_core_ctx2 #(
`ifdef SNOW_ONE_ONE
    parameter integer ONE_ONE = 1          // 0 = 2:1 (Snowflake), 1 = 1:1 baseline
`else
    parameter integer ONE_ONE = 0          // macro makes the choice stick in synthesis
`endif
`ifdef SNOW_NO_OBS
    , parameter integer DEBUG_OBS = 0       // 0 = no observation buses (area measurement)
`else
    , parameter integer DEBUG_OBS = 1
`endif
`ifdef SNOW_CTX1
    , parameter integer NCTX = 1            // area anchor: same RTL, one context
`else
    , parameter integer NCTX = 2            // number of time-multiplexed contexts
`endif
) (
    input  wire        clk,
    input  wire        reset,
    input  wire [NCTX-1:0] start,                   // per-context: run one decoding cycle
    input  wire [NCTX*SNOW_NSYN-1:0] syndrome,      // per-context new-round defects
    output reg  [NCTX-1:0] done,                    // per-context: cycle finished
    output wire        all_busy,
    output reg  [NCTX*SNOW_NCOMMIT-1:0] commit_onehot,  // per-context commit vectors
    output wire [SNOW_NN*SNOW_CID_W-1:0] obs_cid,
    output wire [SNOW_NN-1:0]    obs_active,
    output wire [SNOW_NN-1:0]    obs_whole,
    output wire [SNOW_NN-1:0]    obs_defect,
    output wire [SNOW_NN*SNOW_PTR_W-1:0] obs_ptr,
    output wire [SNOW_NN-1:0]    obs_grown,
    output wire [SNOW_NN-1:0]    obs_unrooted,
    output wire [SNOW_NN-1:0]    obs_busy,
    output wire [SNOW_NE*2-1:0]  obs_growth,
    output wire [SNOW_NE-1:0]    obs_ecorr,
    output wire [$clog2(NCTX)-1:0] dbg_ctx,   // context owning the datapath
    output reg  [2:0]  dbg_stage,
    output reg  [7:0]  dbg_step,
    output reg         dbg_valid
);

  localparam integer NN   = SNOW_NN;
  localparam integer NE   = SNOW_NE;
  localparam integer CW   = SNOW_CID_W;
  localparam integer NDIR = SNOW_NDIR;
  localparam integer CTXW = (NCTX > 1) ? $clog2(NCTX) : 1;

  localparam [2:0] ST_IDLE = 0, ST_DROP = 1, ST_GW = 2, ST_MW = 3, ST_GH = 4, ST_MH = 5;

  // pointer encoding: 0 = C (root), d+1 = direction d
  function automatic [SNOW_PTR_W-1:0] DIR2PTR(input integer d);
    DIR2PTR = d[SNOW_PTR_W-1:0] + 1'b1;
  endfunction
  function automatic integer PTR2DIR(input [SNOW_PTR_W-1:0] p);
    PTR2DIR = p - 1'b1;
  endfunction

  // ---------- state ----------
  reg [CW-1:0]         cid      [0:NCTX*NN-1];
  reg                  active   [0:NCTX*NN-1];
  reg                  whole    [0:NCTX*NN-1];
  reg                  defect   [0:NCTX*NN-1];
  reg [SNOW_PTR_W-1:0] ptr      [0:NCTX*NN-1];
  reg                  grown    [0:NCTX*NN-1];
  reg                  unrooted [0:NCTX*NN-1];
  reg                  busy     [0:NCTX*NN-1];
  reg [1:0]            growth   [0:NCTX*NE-1];
  reg                  ecorr    [0:NCTX*NE-1];

  // ---------- combinational next values ----------
  reg [CW-1:0]         c_cid      [0:NN-1];
  reg                  c_active   [0:NN-1];
  reg                  c_whole    [0:NN-1];
  reg                  c_defect   [0:NN-1];
  reg [SNOW_PTR_W-1:0] c_ptr      [0:NN-1];
  reg                  c_grown    [0:NN-1];
  reg                  c_unrooted [0:NN-1];
  reg                  c_busy     [0:NN-1];
  reg [1:0]            c_growth   [0:NE-1];
  reg                  c_ecorr    [0:NE-1];

  reg [2:0] stage     [0:NCTX-1];
  reg [7:0] step_cnt  [0:NCTX-1];
  reg [SNOW_NSYN-1:0] syn_buf [0:NCTX-1];
  reg       run       [0:NCTX-1];      // context has work (started, not done)
  reg [CTXW-1:0] ctx_sel;              // context owning the datapath this cycle
  reg [CTXW-1:0] dbg_ctx_r;            // registered copy, aligned with dbg_valid
  reg [CTXW-1:0] hold;                 // context kept one drain cycle after done
  reg            hold_valid;
  integer        ctx_scan;             // must NOT be CTXW wide: a 1-bit counter
                                       // never reaches NCTX and the arbiter loop
                                       // would spin forever in zero time
  reg            ctx_found;

  integer n, d, m, e, e2, s, c;      // combinational block
  integer ns, es, cs;                 // sequential block (kept separate)
  reg [SNOW_NW-1:0] nb;
  reg [SNOW_EW-1:0] eb;
  reg       det_def;
  reg [SNOW_NW-1:0] push_to  [0:NN-1];
  reg [SNOW_EW-1:0] push_dir [0:NN-1];
  // localised push bookkeeping (see the merging stage): a push may only travel
  // along a pointer, so it only ever reaches a direct neighbour.
  reg [SNOW_NW-1:0] push_target [0:NN-1];
  reg               has_push    [0:NN-1];
  reg               inc_def;
  reg               flip_u, flip_v;
  reg       grow_pulse [0:NN-1];
  reg [1:0] inc_sum;
  reg       any_c_busy;

  // `busy` is an unpacked array, so the OR reduction needs an explicit loop
  // (a reduction operator on an unpacked array is illegal in SystemVerilog).
  reg     all_busy_r;
  integer bi;
  always @(*) begin
    all_busy_r = 1'b0;
    for (bi = 0; bi < NN; bi = bi + 1) all_busy_r = all_busy_r | busy[ctx_sel*NN + bi];
  end
  assign all_busy = all_busy_r;

  // dbg_ctx must be registered together with dbg_stage/dbg_valid: they are
  // all sampled one cycle after the step, and the arbiter may already have
  // moved to the other context by then (otherwise the testbench dumps the
  // new context's state under the old context's stage).
  assign dbg_ctx = dbg_ctx_r;
  // ---- current-context views of the state (the context mux) ----
  // NOTE: the element width MUST be spelled out -- an unpacked net array
  // declared without a range defaults to 1 bit and silently truncates the
  // cluster ids, which is exactly what broke the first prototype.
  wire [CW-1:0]         cur_cid [0:NN-1];
  wire                  cur_active [0:NN-1];
  wire                  cur_whole [0:NN-1];
  wire                  cur_defect [0:NN-1];
  wire [SNOW_PTR_W-1:0] cur_ptr [0:NN-1];
  wire                  cur_grown [0:NN-1];
  wire                  cur_unrooted [0:NN-1];
  wire                  cur_busy [0:NN-1];
  wire [1:0]            cur_growth [0:NE-1];
  wire                  cur_ecorr [0:NE-1];
  genvar gj;
  generate
    for (gj = 0; gj < NN; gj = gj + 1) begin : ctx_view_n
      assign cur_cid[gj] = cid[ctx_sel*NN + gj];
      assign cur_active[gj] = active[ctx_sel*NN + gj];
      assign cur_whole[gj] = whole[ctx_sel*NN + gj];
      assign cur_defect[gj] = defect[ctx_sel*NN + gj];
      assign cur_ptr[gj] = ptr[ctx_sel*NN + gj];
      assign cur_grown[gj] = grown[ctx_sel*NN + gj];
      assign cur_unrooted[gj] = unrooted[ctx_sel*NN + gj];
      assign cur_busy[gj] = busy[ctx_sel*NN + gj];
    end
    for (gj = 0; gj < NE; gj = gj + 1) begin : ctx_view_e
      assign cur_growth[gj] = growth[ctx_sel*NE + gj];
      assign cur_ecorr[gj] = ecorr[ctx_sel*NE + gj];
    end
  endgenerate


  genvar gi;
  generate
    if (DEBUG_OBS) begin : g_obs
      for (gi = 0; gi < NN; gi = gi + 1) begin : obs_nodes
        assign obs_cid[gi*CW +: CW] = cid[ctx_sel*NN + gi];
        assign obs_active[gi] = active[ctx_sel*NN + gi];
        assign obs_whole[gi] = whole[ctx_sel*NN + gi];
        assign obs_defect[gi] = defect[ctx_sel*NN + gi];
        assign obs_ptr[gi*SNOW_PTR_W +: SNOW_PTR_W] = ptr[ctx_sel*NN + gi];
        assign obs_grown[gi] = grown[ctx_sel*NN + gi];
        assign obs_unrooted[gi] = unrooted[ctx_sel*NN + gi];
        assign obs_busy[gi] = busy[ctx_sel*NN + gi];
      end
      for (gi = 0; gi < NE; gi = gi + 1) begin : obs_edges
        assign obs_growth[gi*2 +: 2] = growth[ctx_sel*NE + gi];
        assign obs_ecorr[gi] = ecorr[ctx_sel*NE + gi];
      end
    end else begin : g_noobs
      // SNOW_NO_OBS: observation buses tied off.  They are pure debug plumbing
      // (a real design would time-multiplex them into a narrow debug port), so
      // the difference against the default build measures their area cost.
      assign obs_cid      = {(NN*CW){1'b0}};
      assign obs_active   = {NN{1'b0}};
      assign obs_whole    = {NN{1'b0}};
      assign obs_defect   = {NN{1'b0}};
      assign obs_ptr      = {(NN*SNOW_PTR_W){1'b0}};
      assign obs_grown    = {NN{1'b0}};
      assign obs_unrooted = {NN{1'b0}};
      assign obs_busy     = {NN{1'b0}};
      assign obs_growth   = {(NE*2){1'b0}};
      assign obs_ecorr    = {NE{1'b0}};
    end
  endgenerate


  always @(*) begin
    for (n = 0; n < NN; n = n + 1) begin
      c_cid[n]      = cur_cid[n];
      c_active[n]   = cur_active[n];
      c_whole[n]    = cur_whole[n];
      c_defect[n]   = cur_defect[n];
      c_ptr[n]      = cur_ptr[n];
      c_grown[n]    = cur_grown[n];
      c_unrooted[n] = cur_unrooted[n];
      c_busy[n]     = 1'b0;
      push_to[n]    = SNOW_NO_NODE;
      push_dir[n]   = SNOW_NO_EDGE;
      grow_pulse[n] = 1'b0;
    end
    for (e = 0; e < NE; e = e + 1) begin
      c_growth[e] = cur_growth[e];
      c_ecorr[e]  = cur_ecorr[e];
    end

    case (stage[ctx_sel])

      // ---------------- DROP ----------------
      ST_DROP: begin
        for (n = 0; n < NN; n = n + 1) begin
          c_grown[n]    = 1'b0;                 // Friendship.drop()
          c_unrooted[n] = 1'b0;
          m = SNOW_NODE_BELOW(n);
          if (m != SNOW_NO_NODE) begin          // NodeFriendship.drop(): slide state down
            c_defect[m] = cur_defect[n];
            c_active[m] = cur_active[n];
            c_cid[m]    = (cur_cid[n] == SNOW_RESET_CID) ? SNOW_RESET_CID
                                                     : (cur_cid[n] + SNOW_CID_DELTA(cur_cid[n]));
            c_ptr[m]    = cur_ptr[n];
            c_whole[m]  = cur_whole[n];
          end
          if (SNOW_IS_TOP(n)) begin             // TopSheetFriendship.drop()
            c_defect[n] = 1'b0;
            c_active[n] = 1'b0;
          end
        end
        for (s = 0; s < SNOW_NSYN; s = s + 1) begin    // _load(syndrome)
          m = SNOW_SYN_NODE(s);
          c_defect[m] = c_defect[m] ^ syn_buf[ctx_sel][s];
        end
        for (e = 0; e < NE; e = e + 1) begin            // edge contacts slide down
          e2 = SNOW_EDGE_ABOVE(e);
          if (e2 != SNOW_NO_EDGE) begin
            c_growth[e] = cur_growth[e2];
            c_ecorr[e]  = cur_ecorr[e2];
          end else begin
            c_growth[e] = 2'd0;                         // no edge above -> reset
            c_ecorr[e]  = 1'b0;
          end
        end
      end

      // ---------------- GROW (whole clusters for 2:1, all active for 1:1) ----
      ST_GW: begin
        for (n = 0; n < NN; n = n + 1) begin
          if (ONE_ONE ? cur_active[n] : (cur_active[n] && cur_whole[n])) begin
            grow_pulse[n] = 1'b1;
            c_whole[n]    = ~cur_whole[n];                  // _grow() flips whole
            // `grown` is only set by the 2:1 schedule's grow_whole()
            if (!ONE_ONE) c_grown[n] = 1'b1;
          end
          // find_broken_pointers() == `'D' in pointer`; see snowflake_core.sv and
          // report 6.32 -- the single-constant comparison misses the SD/WD/NWD
          // (unrotated) and E2D/SED/SWD (rotated) circuit-level directions.
          if (SNOW_IS_BOT(n) && SNOW_PTR_DOWN_MASK[cur_ptr[n]]) begin  // find_broken_pointers()
            c_cid[n] = SNOW_RESET_CID;
            c_ptr[n] = SNOW_PTR_C;
          end
        end
        for (e = 0; e < NE; e = e + 1) begin
          if (cur_growth[e] < 2'd2) begin
            inc_sum = {1'b0, grow_pulse[SNOW_EDGE_U(e)]} + {1'b0, grow_pulse[SNOW_EDGE_V(e)]};
            c_growth[e] = (cur_growth[e] + inc_sum > 2) ? 2'd2 : (cur_growth[e] + inc_sum);
          end
        end
      end

      // ---------------- GROW_HALF (2:1 only) ----------------
      ST_GH: begin
        for (n = 0; n < NN; n = n + 1) begin
          c_unrooted[n] = 1'b0;                 // Node.grow_half() resets unrooted
          if (cur_active[n] && !cur_whole[n] && !cur_grown[n]) begin
            grow_pulse[n] = 1'b1;
            c_whole[n]    = 1'b1;
          end
        end
        for (e = 0; e < NE; e = e + 1) begin
          if (cur_growth[e] < 2'd2) begin
            inc_sum = {1'b0, grow_pulse[SNOW_EDGE_U(e)]} + {1'b0, grow_pulse[SNOW_EDGE_V(e)]};
            c_growth[e] = (cur_growth[e] + inc_sum > 2) ? 2'd2 : (cur_growth[e] + inc_sum);
          end
        end
      end

      // ---------------- MERGING (whole / half) ----------------
      ST_MW, ST_MH: begin
`ifdef SNOW_ABLATE_MERGE
        // SNOW_ABLATE_MERGE: merging datapath deleted (one-cycle no-op).
        // Synthesis-only ablation build: the difference against the default
        // build is the area of the merging logic (flooding compares + pointer
        // update + syncing + push aggregation) -- exactly the combinational
        // part that context switching can share between logical lattices.
        for (n = 0; n < NN; n = n + 1) c_busy[n] = 1'b0;
`else
        // ---- flooding ----
        for (n = 0; n < NN; n = n + 1) begin
          if (cur_cid[n] == SNOW_RESET_CID) begin               // finish unrooting
            c_busy[n]     = 1'b1;
            c_cid[n]      = n[CW-1:0];
            c_unrooted[n] = 1'b1;
          end else begin
            for (d = 0; d < NDIR; d = d + 1) begin
              eb = SNOW_EDGE_OF(n, d);
              nb = SNOW_NB(n, d);
              if ((eb != SNOW_NO_EDGE) && (nb != SNOW_NO_NODE) && (cur_growth[eb] == 2'd2)) begin
                if (cur_cid[nb] == SNOW_RESET_CID) begin
                  if (!cur_unrooted[n]) begin                   // start unrooting self, then break
                    c_busy[n] = 1'b1;
                    c_cid[n]  = SNOW_RESET_CID;
                    c_ptr[n]  = SNOW_PTR_C;
                    break;                                  // synthesis-safe early exit
                  end else if ((stage[ctx_sel] == ST_MW) && cur_grown[nb] && !c_grown[n]) begin
                    c_busy[n] = 1'b1;
                    c_grown[n] = 1'b1;
                  end
                end else begin
                  if (cur_cid[nb] < c_cid[n]) begin             // _compare_cid
                    c_busy[n] = 1'b1;
                    c_ptr[n]  = DIR2PTR(d);
                    c_cid[n]  = cur_cid[nb];
                  end
                  if ((stage[ctx_sel] == ST_MW) && cur_grown[nb] && !c_grown[n]) begin   // _check_grown
                    c_busy[n] = 1'b1;
                    c_grown[n] = 1'b1;
                  end
                end
              end
            end
          end
        end
        // ---- syncing (fast merger: uses the pointer updated by flooding) ----
        for (n = 0; n < NN; n = n + 1) begin
          det_def = (!SNOW_IS_BND(n)) && cur_defect[n];
          has_push[n]    = 1'b0;
          push_target[n] = SNOW_NO_NODE;
          push_dir[n]    = SNOW_NO_EDGE;
          if (c_ptr[n] == SNOW_PTR_C) begin
            c_active[n] = det_def;                          // root: active iff it holds a defect
          end else begin
            d  = PTR2DIR(c_ptr[n]);
            nb = SNOW_NB(n, d);
            c_active[n] = cur_active[nb];
            if (det_def) begin                              // push defect along pointer
              c_busy[n]      = 1'b1;
              has_push[n]    = 1'b1;
              push_target[n] = nb;
              push_dir[n]    = SNOW_EDGE_OF(n, d);
            end
          end
          if (cur_active[n] != c_active[n]) c_busy[n] = 1'b1;
        end
        // ---- apply defect pushes and correction flips, locally ----
        // Semantically identical to
        //     c_defect[push_to[n]] ^= 1; c_defect[n] ^= 1; c_ecorr[push_dir[n]] ^= 1
        // for every pushing node n, but written without any variable index on a
        // state array: a push can only travel along a pointer, so it can only
        // reach a direct neighbour, and an edge can only be flipped by one of
        // its two endpoints.  The original form synthesised into an N x N write
        // crossbar whose cost grows as O(N^2) and which dominated both the area
        // (43% of the surface d=5 build) and the critical path of the flat
        // design (cid -> compare -> pointer -> push -> defect, 52% of it route).
        for (n = 0; n < NN; n = n + 1) begin
          inc_def = 1'b0;
          for (d = 0; d < NDIR; d = d + 1) begin
            m = SNOW_NB(n, d);
            if ((m != SNOW_NO_NODE) && has_push[m] && (push_target[m] == n))
              inc_def = inc_def ^ 1'b1;                     // two pushes cancel
          end
          if (inc_def) begin
            c_defect[n] = c_defect[n] ^ 1'b1;
            c_busy[n]   = 1'b1;
          end
          if (has_push[n]) c_defect[n] = c_defect[n] ^ 1'b1;
        end
        for (e = 0; e < NE; e = e + 1) begin
          flip_u = 1'b0;
          flip_v = 1'b0;
          m = SNOW_EDGE_U(e);
          if ((m != SNOW_NO_NODE) && has_push[m] && (push_dir[m] == e)) flip_u = 1'b1;
          m = SNOW_EDGE_V(e);
          if ((m != SNOW_NO_NODE) && has_push[m] && (push_dir[m] == e)) flip_v = 1'b1;
          if (flip_u ^ flip_v) c_ecorr[e] = c_ecorr[e] ^ 1'b1;
        end
`endif // SNOW_ABLATE_MERGE
      end

      default: ;
    endcase

    any_c_busy = 1'b0;
    for (n = 0; n < NN; n = n + 1) any_c_busy = any_c_busy | c_busy[n];
  end


  // ---- context arbiter: one ready context advances per clock ----------
  // `hold` is a one-cycle drain: after a context finishes, the arbiter keeps
  // pointing at it for one more clock (with ctx_found=0, so the datapath does
  // NOT advance).  Without it, the debug/observation buses switch to the next
  // context in the very cycle the finished context's last step is sampled, and
  // the testbench records the wrong context's state for that step.
  // Cost: NCTX idle cycles per round.
  always @(*) begin
    if (hold_valid) begin
      ctx_sel   = hold;
      ctx_found = 1'b0;
    end else begin
      ctx_sel   = {CTXW{1'b0}};
      ctx_found = 1'b0;
      for (ctx_scan = 0; ctx_scan < NCTX; ctx_scan = ctx_scan + 1) begin
        if (!ctx_found && run[ctx_scan]) begin
          ctx_sel   = ctx_scan;
          ctx_found = 1'b1;
        end
      end
    end
  end

  // ================== controller + state update ==================
  always @(posedge clk) begin
    if (reset) begin
      for (cs = 0; cs < NCTX; cs = cs + 1) begin
        for (ns = 0; ns < NN; ns = ns + 1) begin
          cid[cs*NN + ns]      <= ns[CW-1:0];
          active[cs*NN + ns]   <= 1'b0;
          whole[cs*NN + ns]    <= 1'b1;
          defect[cs*NN + ns]   <= 1'b0;
          ptr[cs*NN + ns]      <= SNOW_PTR_C;
          grown[cs*NN + ns]    <= 1'b0;
          unrooted[cs*NN + ns] <= 1'b0;
          busy[cs*NN + ns]     <= 1'b0;
        end
        for (es = 0; es < NE; es = es + 1) begin
          growth[cs*NE + es] <= 2'd0;
          ecorr[cs*NE + es]  <= 1'b0;
        end
        stage[cs]    <= ST_IDLE;
        step_cnt[cs] <= 8'd0;
        run[cs]      <= 1'b0;
      end
      done <= {NCTX{1'b0}};
      dbg_stage <= ST_IDLE;
      dbg_step <= 8'd0;
      dbg_valid <= 1'b0;
      commit_onehot <= {(NCTX*SNOW_NCOMMIT){1'b0}};
    end else begin
      dbg_valid <= 1'b0;
      for (cs = 0; cs < NCTX; cs = cs + 1) begin
        if (start[cs] && !run[cs]) begin
          run[cs]      <= 1'b1;
          stage[cs]    <= ST_DROP;
          step_cnt[cs] <= 8'd1;
          syn_buf[cs]  <= syndrome[cs*SNOW_NSYN +: SNOW_NSYN];
        end
      end
      // done / commit are one-clock pulses for EVERY context: clearing only
      // the selected one would leave stale pulses behind and the testbench
      // would think a context finished when it did not.
      done <= {NCTX{1'b0}};
      hold_valid <= 1'b0;
      hold <= {CTXW{1'b0}};
      commit_onehot <= {(NCTX*SNOW_NCOMMIT){1'b0}};

      case (stage[ctx_sel])
        ST_IDLE: if (ctx_found) begin
                   // a context that has been started but has not run yet
                 end
        ST_DROP: begin stage[ctx_sel] <= ST_GW; step_cnt[ctx_sel] <= 8'd1; end
        ST_GW:   begin stage[ctx_sel] <= ST_MW; step_cnt[ctx_sel] <= 8'd1; end
`ifdef SNOW_BUSYREG
        // V2d: the quiescence check feeds the FSM clock enable and, in the
        // flat build, its OR reduction over all nodes is the new critical path
        // (report: cid -> ... -> stage_reg/CE, 26 levels, 57% of it routing).
        // The per-node busy flags are already registers, so all_busy (= OR of
        // them) is a pure FF -> OR-tree -> CE path with no deep logic in front
        // of it.  `step_cnt > 1` is needed because on the first merging cycle
        // those flags still come from the previous stage (nothing busy there).
        // Cost: exactly one extra clock per merging phase; that clock provably
        // changes nothing (no node updates when nothing is busy), so it is
        // hidden from the trace by the dbg_valid rule below.
        ST_MW:   begin
                   if (!all_busy && (step_cnt[ctx_sel] > 8'd1)) begin
                     if (ONE_ONE) begin
                       stage[ctx_sel] <= ST_IDLE; step_cnt[ctx_sel] <= 8'd0; done[ctx_sel] <= 1'b1; run[ctx_sel] <= 1'b0;
                     hold <= ctx_sel; hold_valid <= 1'b1;
                     end else begin
                       stage[ctx_sel] <= ST_GH; step_cnt[ctx_sel] <= 8'd1;
                     end
                   end else step_cnt[ctx_sel] <= step_cnt[ctx_sel] + 8'd1;
                 end
        ST_GH:   begin stage[ctx_sel] <= ST_MH; step_cnt[ctx_sel] <= 8'd1; end
        ST_MH:   begin
                   if (!all_busy && (step_cnt[ctx_sel] > 8'd1)) begin
                     stage[ctx_sel] <= ST_IDLE; step_cnt[ctx_sel] <= 8'd0; done[ctx_sel] <= 1'b1; run[ctx_sel] <= 1'b0;
                     hold <= ctx_sel; hold_valid <= 1'b1;
                   end else step_cnt[ctx_sel] <= step_cnt[ctx_sel] + 8'd1;
                 end
`else
        ST_MW:   begin
                   if (!any_c_busy) begin
                     if (ONE_ONE) begin                 // 1:1 -> cycle ends after merging
                       stage[ctx_sel] <= ST_IDLE; step_cnt[ctx_sel] <= 8'd0; done[ctx_sel] <= 1'b1; run[ctx_sel] <= 1'b0;
                     hold <= ctx_sel; hold_valid <= 1'b1;
                     end else begin
                       stage[ctx_sel] <= ST_GH; step_cnt[ctx_sel] <= 8'd1;
                     end
                   end else step_cnt[ctx_sel] <= step_cnt[ctx_sel] + 8'd1;
                 end
        ST_GH:   begin stage[ctx_sel] <= ST_MH; step_cnt[ctx_sel] <= 8'd1; end
        ST_MH:   begin
                   if (!any_c_busy) begin
                     stage[ctx_sel] <= ST_IDLE; step_cnt[ctx_sel] <= 8'd0; done[ctx_sel] <= 1'b1; run[ctx_sel] <= 1'b0;
                     hold <= ctx_sel; hold_valid <= 1'b1;
                   end else step_cnt[ctx_sel] <= step_cnt[ctx_sel] + 8'd1;
                 end
`endif
        default: stage[ctx_sel] <= ST_IDLE;
      endcase

      if (ctx_found && (stage[ctx_sel] != ST_IDLE)) begin
        for (ns = 0; ns < NN; ns = ns + 1) begin
          cid[ctx_sel*NN + ns]      <= c_cid[ns];
          active[ctx_sel*NN + ns]   <= c_active[ns];
          whole[ctx_sel*NN + ns]    <= c_whole[ns];
          defect[ctx_sel*NN + ns]   <= c_defect[ns];
          ptr[ctx_sel*NN + ns]      <= c_ptr[ns];
          grown[ctx_sel*NN + ns]    <= c_grown[ns];
          unrooted[ctx_sel*NN + ns] <= c_unrooted[ns];
          busy[ctx_sel*NN + ns]     <= c_busy[ns];
        end
        for (es = 0; es < NE; es = es + 1) begin
          growth[ctx_sel*NE + es] <= c_growth[es];
          ecorr[ctx_sel*NE + es]  <= c_ecorr[es];
        end
        dbg_stage <= stage[ctx_sel];
        dbg_step  <= step_cnt[ctx_sel];
        dbg_ctx_r <= ctx_sel;
`ifdef SNOW_BUSYREG
        // suppress the extra exit clock so the trace stays line-identical to
        // the localuf golden trace
        dbg_valid <= !(((stage[ctx_sel] == ST_MW) || (stage[ctx_sel] == ST_MH)) && !all_busy
                       && (step_cnt > 8'd1));
`else
        dbg_valid <= 1'b1;
`endif
        if (stage[ctx_sel] == ST_DROP) begin
          for (es = 0; es < NE; es = es + 1)
            if (SNOW_IS_COMMIT(es) && ecorr[ctx_sel*NE + es])
              commit_onehot[ctx_sel*SNOW_NCOMMIT + SNOW_COMMIT_IDX(es)] <= 1'b1;
        end
      end
    end
  end

endmodule
